* from {{m|en|mull|t=(''Northern England'') something reduced to fine particles|pos=noun}}<ref>{{R:OED Online|entry=mull|pos=''n.''{{sup|1}}|noformat=1|id=5737936299|date=July 2023}}</ref> or {{affix|en|mull|t1=(''chiefly Northern England'') to grind to powder, crumble, powder, pulverize|pos1=verb|-er|pos2={{glossary|suffix}} forming {{glossary|agent noun}}s}} (see [[#Etymology 2|etymology 2]]); or
